from .generated_state import (
    IZOM_PROPUI_FREE_BLENDER_IDENTIFIER_LIMIT,
    IZOM_PROPUI_FREE_GENERATED_SCRIPT_PER_UI_PREFIX,
    IZOM_PROPUI_FREE_GENERATED_SCRIPT_REGISTRY_KEY,
    IZOM_PROPUI_FREE_GENERATED_SCRIPT_REGISTRY_PREFIX,
)


IZOM_PROPUI_FREE_GENERATED_BRANDING_DEFAULTS = {
    'show_credit': True,
    'credit_comment': 'Auto-generated by izom PropUI Free.',
}


def _izom_propui_free_limit_prefix_for_digest(prefix, digest, *, limit=IZOM_PROPUI_FREE_BLENDER_IDENTIFIER_LIMIT):
    digest_text = str(digest or '').strip()
    prefix_text = str(prefix or '').strip('_') + '_'
    if len(prefix_text) + len(digest_text) <= limit:
        return f"{prefix_text}{digest_text}"
    available = max(1, limit - len(digest_text) - 1)
    return f"{prefix_text[:available].rstrip('_')}_{digest_text}"[:limit]


def izom_propui_free_normalize_generated_branding(_branding=None):
    return dict(IZOM_PROPUI_FREE_GENERATED_BRANDING_DEFAULTS)


def izom_propui_free_generated_branding_from_params(_params):
    return izom_propui_free_normalize_generated_branding()


def izom_propui_free_resolve_generated_branding(_branding=None):
    normalized = izom_propui_free_normalize_generated_branding()
    return {
        **normalized,
        'text_datablock_prefix': IZOM_PROPUI_FREE_GENERATED_SCRIPT_PER_UI_PREFIX.rstrip('_'),
        'script_per_ui_prefix': IZOM_PROPUI_FREE_GENERATED_SCRIPT_PER_UI_PREFIX,
        'registry_key': IZOM_PROPUI_FREE_GENERATED_SCRIPT_REGISTRY_KEY,
        'registry_prefix': IZOM_PROPUI_FREE_GENERATED_SCRIPT_REGISTRY_PREFIX,
    }


def izom_propui_free_generated_panel_class_name(branding, digest):
    return _izom_propui_free_limit_prefix_for_digest('IZOM_PROPUI_FREE_PT_', digest)


def izom_propui_free_is_branded_registry_key(registry_key):
    key_text = str(registry_key or '').strip()
    return key_text.startswith(IZOM_PROPUI_FREE_GENERATED_SCRIPT_REGISTRY_PREFIX)


def izom_propui_free_is_branded_panel_class_name(name):
    name_text = str(name or '').strip()
    if len(name_text) <= 16:
        return False
    suffix = name_text[-16:]
    prefix = name_text[:-16]
    return (
        bool(prefix.startswith('IZOM_PROPUI_FREE_PT_'))
        and all(char in '0123456789abcdef' for char in suffix)
        and all(char.isalnum() or char == '_' for char in name_text)
        and not name_text[0].isdigit()
    )


def izom_propui_free_brand_generated_python_source(source, _branding=None):
    return str(source or '')


from ..core.exports import izom_propui_free_public_names  # noqa: E402,F401

__all__ = izom_propui_free_public_names(globals(), all_public=True)
